pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner) public {
        vm.assume(nonOwner != address(c).balance); // ensure nonOwner is not the owner (owner is set in constructor)
        vm.startPrank(nonOwner);
        bool ok;
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();
        assertTrue(!ok);
    }
}
